package com.example.bmmoney;
import android.content.*;import android.os.*;import android.text.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.recyclerview.widget.*;import com.example.bmmoney.adapter.TransactionAdapter;import com.example.bmmoney.data.*;import java.util.*;
public class SearchActivity extends AppCompatActivity{private AppDatabase db;private TransactionAdapter adapter;private EditText edtSearch;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_search);ThemeManager.apply(this);db=AppDatabase.getInstance(this);edtSearch=findViewById(R.id.edtSearch);RecyclerView rv=findViewById(R.id.recyclerSearch);rv.setLayoutManager(new LinearLayoutManager(this));adapter=new TransactionAdapter();rv.setAdapter(adapter);setupSearch();setupNav();filter("");}@Override protected void onResume(){super.onResume();filter(edtSearch==null?"":edtSearch.getText().toString());}private void setupSearch(){edtSearch.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int st,int b,int c){filter(s.toString());}});}private void filter(String kw){List<TransactionEntity> all=db.transactionDao().getAllTransactions();if(kw==null||kw.trim().isEmpty()){adapter.setTransactions(all);return;}String q=kw.toLowerCase(Locale.ROOT).trim();List<TransactionEntity> out=new ArrayList<>();for(TransactionEntity t:all){String title=t.getTitle()==null?"":t.getTitle().toLowerCase(Locale.ROOT);String cat=t.getCategory()==null?"":t.getCategory().toLowerCase(Locale.ROOT);String note=t.getNote()==null?"":t.getNote().toLowerCase(Locale.ROOT);String type="INCOME".equals(t.getType())?"thu nhập income":"chi tiêu expense";if(title.contains(q)||cat.contains(q)||note.contains(q)||type.contains(q))out.add(t);}adapter.setTransactions(out);}private void setupNav(){findViewById(R.id.navHome).setOnClickListener(v->startActivity(new Intent(this,MainActivity.class)));findViewById(R.id.navAdd).setOnClickListener(v->startActivity(new Intent(this,AddTransactionActivity.class)));findViewById(R.id.navReport).setOnClickListener(v->startActivity(new Intent(this,ReportActivity.class)));findViewById(R.id.navSearch).setOnClickListener(v->{});findViewById(R.id.navSettings).setOnClickListener(v->startActivity(new Intent(this,SettingsActivity.class)));}}
